<script lang="ts" setup>
import { computed,onMounted,ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Alert as AAlert, Button as AButton, Card as ACard, Col as ACol, Drawer as ADrawer, Form as AForm, FormItem as AFormItem, Input as AInput, Textarea as ATextarea, InputNumber as AInputNumber, Row as ARow, Select as ASelect, Space as ASpace, Switch as ASwitch, Table as ATable, Tabs as ATabs, TabPane as ATabPane, Tag as ATag, Tooltip as ATooltip, message } from 'ant-design-vue';
import { QuestionCircleOutlined } from '@ant-design/icons-vue';
import { type PageResult,useServerPagination } from '#/utils/server-pagination';
import ServerEditorDrawer from '#/components/openresty/ServerEditorDrawer.vue';
type Center={id:string;code:string;name:string};type Node={id:string;name:string;host:string;servicePort:number;enabled:boolean};type Server={id:string;domain:string;listenPort:number;sslEnabled:boolean;certificateId?:string;upstreamId?:string;accessLog?:string;errorLog?:string;rootPath?:string;hideVersion:boolean;responseHeaders:string[]};
const router=useRouter(),route=useRoute(),centers=ref<Center[]>([]),nodes=ref<Node[]>([]),rows=ref<Server[]>([]),centerId=ref<string>(),nodeId=ref<string>(),active=ref('basic'),loading=ref(false),serverDrawerOpen=ref(false),editingServerId=ref<string>();const serverForm=ref({domain:'',listenPort:80,sslEnabled:false,upstreamId:undefined as string|undefined,accessLog:'',errorLog:''});const pager=useServerPagination();const defaults:any={rootPath:'',hideVersion:true,responseHeaders:['X-Frame-Options: SAMEORIGIN','X-Content-Type-Options: nosniff','Referrer-Policy: strict-origin-when-cross-origin'],mimeTypesPath:'/etc/nginx/mime.types',defaultType:'application/octet-stream',sendfileEnabled:true,tcpNopushEnabled:true,tcpNodelayEnabled:true,resetTimedoutConnection:false,keepaliveTimeoutSeconds:65,keepaliveRequests:1000,keepaliveTime:'1h',clientMaxBodySize:'10m',clientHeaderBufferSize:'1k',largeClientHeaderBuffers:'4 8k',serverNamesHashBucketSize:512,gzipEnabled:true,gzipMinLength:'1k',gzipCompLevel:2,httpLogFormat:'openresty_plus \'$remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent\'',streamLogFormat:'openresty_plus_stream \'$remote_addr [$time_local] $protocol $status $bytes_sent $bytes_received $session_time\'',defaultPages:{},defaultPageKey:'404.html'};const settings=ref({...defaults});const numeric=ref({timeout:65,timeoutUnit:'s',bodySize:10,bodyUnit:'m',headerBuffer:1,headerUnit:'k',gzipMin:1,gzipUnit:'k',largeCount:4,largeSize:8,largeUnit:'k'});
const defaultPageDefinitions=[{key:'404.html',label:'网站 404 错误页',hint:'用于静态网站与 PHP 网站的 404 页面。'},{key:'site-not-found.html',label:'网站不存在页',hint:'用于未匹配站点时展示的页面。'},{key:'index.html',label:'静态网站默认页',hint:'创建静态站点时使用的默认 index.html。'},{key:'index.php',label:'PHP 网站默认页',hint:'创建 PHP 网站时使用的默认 index.php。'},{key:'site-suspended.html',label:'网站停用页',hint:'站点暂停运行时展示的页面。'}];
defaults.errorPages={'404':'<!doctype html><html><body><h1>404</h1></body></html>'};
const errorPagePresets=Array.from({length:200},(_,i)=>String(400+i));const selectedErrorPage=ref('404');const customErrorCodes=ref<string[]>([]);const errorPageOptions=computed(()=>[...new Set([...errorPagePresets,...customErrorCodes.value])].filter(v=>Number(v)<=599).map(code=>({value:code,label:`HTTP ${code}${Number(code)>=500?' · 服务端错误':' · 客户端错误'}`})));function addErrorPage(){const code=prompt('请输入 100-599 的 HTTP 状态码');if(!code||!/^[1-5][0-9]{2}$/.test(code)){if(code)message.warning('状态码必须是 100-599');return}if(!customErrorCodes.value.includes(code))customErrorCodes.value.push(code);selectedErrorPage.value=code;settings.value.errorPages??={};settings.value.errorPages[code]??=`<!doctype html>\n<html><body><h1>${code}</h1><p>请求处理失败。</p></body></html>`}
const securityPresets=[{name:'X-Frame-Options',value:'SAMEORIGIN',label:'防点击劫持'},{name:'X-Content-Type-Options',value:'nosniff',label:'防 MIME 嗅探'},{name:'Strict-Transport-Security',value:'max-age=31536000; includeSubDomains',label:'强制 HTTPS（HSTS）'},{name:'Content-Security-Policy',value:"default-src 'self'",label:'内容安全策略（CSP）'},{name:'Referrer-Policy',value:'strict-origin-when-cross-origin',label:'来源信息保护'},{name:'Permissions-Policy',value:'geolocation=(), microphone=(), camera=()',label:'浏览器能力限制'}];
const customHeaders=ref<{name:string;value:string}[]>([]);const headerNameOptions=securityPresets.map(v=>({value:v.name,label:v.name}));
function headerKey(v:{name:string;value:string}){return `${v.name}: ${v.value}`}
function isPresetEnabled(p:any){return settings.value.responseHeaders.includes(`${p.name}: ${p.value}`)}
function togglePreset(p:any,enabled:boolean){const key=`${p.name}: ${p.value}`;settings.value.responseHeaders=enabled?[...new Set([...settings.value.responseHeaders,key])]:settings.value.responseHeaders.filter(v=>v!==key)}
function syncCustomHeaders(){customHeaders.value=settings.value.responseHeaders.filter(v=>!securityPresets.some(p=>v===`${p.name}: ${p.value}`)).map(v=>{const i=v.indexOf(':');return {name:i>0?v.slice(0,i).trim():v,value:i>0?v.slice(i+1).trim():''}})}
function addCustomHeader(){customHeaders.value.push({name:'',value:''})}
function removeCustomHeader(i:number){customHeaders.value.splice(i,1)}
function saveHeaders(){const values=[...settings.value.responseHeaders.filter(v=>securityPresets.some(p=>v===`${p.name}: ${p.value}`)),...customHeaders.value.filter(v=>v.name.trim()).map(headerKey)];settings.value.responseHeaders=values;return save()}
const center=computed(()=>centers.value.find(v=>v.id===centerId.value));const node=computed(()=>nodes.value.find(v=>v.id===nodeId.value));const contextHelp=computed(()=>`配置层级：${center.value?.name||'—'} → ${node.value?`${node.value.name}（${node.value.host}:${node.value.servicePort}）`:'全部实例'} → http {}。此处只维护 HTTP 块指令。`);const columns=[{dataIndex:'domain',key:'domain',title:'域名'},{dataIndex:'listenPort',key:'listenPort',title:'监听端口',width:120},{key:'ssl',title:'TLS',width:100},{key:'root',title:'root 目录'},{key:'action',title:'操作',width:150}];
async function request<T>(path:string,options?:RequestInit):Promise<T>{const r=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(options?.headers??{})}});if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.detail||b.message||'请求失败')}return r.status===204?undefined as T:r.json() as Promise<T>}
async function loadServers(){if(!centerId.value)return;rows.value=pager.apply(await request<PageResult<Server>>(`/centers/${centerId.value}/http/servers/paged?${pager.query()}`))}
async function selectCenter(id:string){centerId.value=id;pager.reset();try{const values=await Promise.all([request<Node[]>(`/centers/${id}/nodes`),request<any>(`/centers/${id}/http/settings`)]);nodes.value=values[0];settings.value={...defaults,...values[1]};const parse=(v:any,f:number)=>{const m=String(v??'').match(/^([\d.]+)([a-z]+)?$/i);return {value:m?Number(m[1]):f,unit:(m?.[2]||'').toLowerCase()||undefined}};const body=parse(settings.value.clientMaxBodySize,10),header=parse(settings.value.clientHeaderBufferSize,1),gzip=parse(settings.value.gzipMinLength,1),large=String(settings.value.largeClientHeaderBuffers||'4 8k').match(/^(\d+)\s+([\d.]+)([a-z]+)$/i);numeric.value={timeout:Number.parseFloat(String(settings.value.keepaliveTimeoutSeconds))||65,timeoutUnit:(String(settings.value.keepaliveTimeoutSeconds).match(/[a-z]+$/i)?.[0]||'s').toLowerCase(),bodySize:body.value,bodyUnit:body.unit||'m',headerBuffer:header.value,headerUnit:header.unit||'k',gzipMin:gzip.value,gzipUnit:gzip.unit||'k',largeCount:large?Number(large[1]):4,largeSize:large?Number(large[2]):8,largeUnit:large?.[3]?.toLowerCase()||'k'};syncCustomHeaders();const requestedNode=String(route.query.nodeId||'');nodeId.value=nodes.value.some(v=>v.id===requestedNode)?requestedNode:(nodes.value.find(v=>v.enabled)?.id||nodes.value[0]?.id);await loadServers()}catch(e){message.error(e instanceof Error?e.message:'加载 HTTP 配置失败')}}
async function save(){if(!centerId.value)return;const multipliers:Record<string,number>={s:1,m:60,h:3600};const keepaliveTimeoutSeconds=Math.round(Number(numeric.value.timeout)*multipliers[numeric.value.timeoutUnit]);if(!Number.isInteger(keepaliveTimeoutSeconds)||keepaliveTimeoutSeconds<1||keepaliveTimeoutSeconds>3600){message.warning('keepalive_timeout 需要在 1 秒至 1 小时之间');return}try{const payload={...settings.value,keepaliveTimeoutSeconds,clientMaxBodySize:`${numeric.value.bodySize}${numeric.value.bodyUnit}`,clientHeaderBufferSize:`${numeric.value.headerBuffer}${numeric.value.headerUnit}`,largeClientHeaderBuffers:`${numeric.value.largeCount} ${numeric.value.largeSize}${numeric.value.largeUnit}`,gzipMinLength:`${numeric.value.gzipMin}${numeric.value.gzipUnit}`};await request(`/centers/${centerId.value}/http/settings`,{method:'PUT',body:JSON.stringify(payload)});settings.value={...settings.value,...payload};window.dispatchEvent(new Event('openresty-config-saved'));message.success('HTTP 块指令已保存，已加入待发布变更')}catch(e){message.error(e instanceof Error?e.message:'保存失败')}}
function openServer(record:Server){editingServerId.value=record.id;serverForm.value={domain:record.domain,listenPort:record.listenPort,sslEnabled:record.sslEnabled,upstreamId:record.upstreamId,accessLog:record.accessLog||'',errorLog:record.errorLog||''};serverDrawerOpen.value=true}
async function saveServer(){if(!centerId.value||!editingServerId.value)return;try{await request(`/centers/${centerId.value}/http/servers/${editingServerId.value}`,{method:'PUT',body:JSON.stringify(serverForm.value)});serverDrawerOpen.value=false;await loadServers();message.success('Server 配置已保存')}catch(e){message.error(e instanceof Error?e.message:'保存 Server 配置失败')}}
onMounted(async()=>{try{centers.value=await request<Center[]>('/centers');const requested=String(route.query.centerId||'');const target=centers.value.find(v=>v.id===requested)||centers.value[0];if(target)await selectCenter(target.id)}catch(e){message.error(e instanceof Error?e.message:'加载中心失败')}});
</script>
<template><div class="ops-page http-overview"><a-card :bordered="false" title="HTTP 块配置"><a-form layout="inline"><a-form-item label="配置中心"><a-select v-model:value="centerId" class="w-72" :options="centers.map(v=>({value:v.id,label:`${v.name}（${v.code}）`}))" @change="selectCenter"/></a-form-item><a-form-item label="OpenResty 实例"><a-select v-model:value="nodeId" class="w-96" :options="nodes.map(v=>({value:v.id,label:`${v.name}（${v.host}:${v.servicePort}）`}))"/></a-form-item></a-form><a-tooltip :title="contextHelp"><QuestionCircleOutlined class="context-help" /></a-tooltip></a-card><a-tabs v-model:active-key="active" class="http-level-tabs mt-4"><a-tab-pane key="basic" tab="基础与性能"><a-card :bordered="false"><template #title><span>基础与性能</span></template><template #extra><a-tooltip title="配置 HTTP 全局基础、文件服务、连接复用与压缩参数。"><span class="section-help"><QuestionCircleOutlined /> 配置说明</span></a-tooltip></template><a-form layout="vertical" class="mt-4 directive-form"><a-row :gutter="16"><a-col :lg="8" :xs="24"><a-form-item label="MIME 类型文件" extra="include：加载 MIME 映射；填写节点内 mime.types 的绝对路径。"><a-input v-model:value="settings.mimeTypesPath" placeholder="/etc/nginx/mime.types"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="默认响应类型" extra="default_type：未匹配 MIME 时返回的类型，例如 application/octet-stream。"><a-input v-model:value="settings.defaultType" placeholder="application/octet-stream"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="root 内容目录" extra="root：静态文件默认根目录；Server 或 Location 可覆盖。"><a-input v-model:value="settings.rootPath" placeholder="/srv/openresty-content"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="server_names_hash_bucket_size" extra="Server 域名哈希桶大小；域名多或长时应调大，最小 32。"><a-input-number v-model:value="settings.serverNamesHashBucketSize" :min="32" class="w-full"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="keepalive_timeout" extra="客户端空闲长连接保留时长；数值加 s、m、h 单位。"><a-space-compact block class="compact-unit-row"><a-input-number v-model:value="numeric.timeout" :min="0"/><a-select v-model:value="numeric.timeoutUnit" :options="[{value:'s',label:'秒（s）'},{value:'m',label:'分钟（m）'},{value:'h',label:'小时（h）'}]"/></a-space-compact></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="keepalive_requests" extra="每个客户端长连接最多处理的请求数。"><a-input-number v-model:value="settings.keepaliveRequests" :min="1" class="w-full"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="keepalive_time" extra="长连接最长存活时长，例如 1h、30m。"><a-input v-model:value="settings.keepaliveTime" placeholder="1h"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="client_max_body_size（支持 k/m/g）" extra="请求体最大尺寸，超出时返回 413；数值加 k、m 或 g。"><a-space-compact block class="compact-unit-row"><a-input-number v-model:value="numeric.bodySize" :min="0"/><a-select v-model:value="numeric.bodyUnit" :options="[{value:'k',label:'千字节（k）'},{value:'m',label:'兆字节（m）'},{value:'g',label:'吉字节（g）'}]"/></a-space-compact></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="client_header_buffer_size" extra="读取普通请求头使用的缓冲区大小；数值加 k 或 m。"><a-space-compact block class="compact-unit-row"><a-input-number v-model:value="numeric.headerBuffer" :min="0"/><a-select v-model:value="numeric.headerUnit" :options="[{value:'k',label:'千字节（k）'},{value:'m',label:'兆字节（m）'}]"/></a-space-compact></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="large_client_header_buffers" extra="超大请求头缓冲区组：依次填写数量、单个大小、单位。"><a-space-compact block class="compact-unit-row large-buffer-row"><a-input-number v-model:value="numeric.largeCount" :min="1"/><a-input-number v-model:value="numeric.largeSize" :min="1"/><a-select v-model:value="numeric.largeUnit" :options="[{value:'k',label:'千字节（k）'},{value:'m',label:'兆字节（m）'}]"/></a-space-compact></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="gzip" extra="是否启用响应压缩。"><a-switch v-model:checked="settings.gzipEnabled" checked-children="开启" un-checked-children="关闭"/></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="gzip_min_length（支持 k/m/g）" extra="响应达到此大小才压缩；数值加 k、m 或 g。"><a-space-compact block class="compact-unit-row"><a-input-number v-model:value="numeric.gzipMin" :min="0"/><a-select v-model:value="numeric.gzipUnit" :options="[{value:'k',label:'千字节（k）'},{value:'m',label:'兆字节（m）'}]"/></a-space-compact></a-form-item></a-col><a-col :lg="8" :xs="24"><a-form-item label="gzip_comp_level" extra="压缩等级，1 更快，9 压缩率更高且更耗 CPU。"><a-input-number v-model:value="settings.gzipCompLevel" :min="1" :max="9" class="w-full"/></a-form-item></a-col></a-row><a-row :gutter="16" class="mt-1"><a-col :lg="6" :sm="12" :xs="24"><div class="security-header-row"><div><div class="font-medium">sendfile</div><div class="text-xs text-gray-500">启用内核高效文件传输；开关控制生成 on 或 off。</div></div><a-switch v-model:checked="settings.sendfileEnabled" checked-children="开启" un-checked-children="关闭"/></div></a-col><a-col :lg="6" :sm="12" :xs="24"><div class="security-header-row"><div><div class="font-medium">tcp_nopush</div><div class="text-xs text-gray-500">配合 sendfile 合并响应包后发送，适合大文件。</div></div><a-switch v-model:checked="settings.tcpNopushEnabled" checked-children="开启" un-checked-children="关闭"/></div></a-col><a-col :lg="6" :sm="12" :xs="24"><div class="security-header-row"><div><div class="font-medium">tcp_nodelay</div><div class="text-xs text-gray-500">立即发送小数据包，降低长连接的交互延迟。</div></div><a-switch v-model:checked="settings.tcpNodelayEnabled" checked-children="开启" un-checked-children="关闭"/></div></a-col><a-col :lg="6" :sm="12" :xs="24"><div class="security-header-row"><div><div class="font-medium">reset_timedout_connection</div><div class="text-xs text-gray-500">读取超时时直接重置连接并释放资源。</div></div><a-switch v-model:checked="settings.resetTimedoutConnection" checked-children="开启" un-checked-children="关闭"/></div></a-col></a-row><div class="mt-5"><a-button type="primary" @click="save">保存基础与性能配置</a-button></div></a-form></a-card></a-tab-pane><a-tab-pane key="security" tab="日志与安全"><a-card :bordered="false"><template #title><span>日志格式</span></template><template #extra><a-tooltip title="log_format：定义访问日志每一行记录的字段；access_log 会引用对应格式。"><span class="section-help"><QuestionCircleOutlined /> 配置说明</span></a-tooltip></template><a-form layout="vertical" class="mt-4"><a-form-item label="HTTP 日志格式" extra="log_format：可使用 $remote_addr、$request、$status 等 Nginx 变量；填写格式名称和字段表达式。"><a-textarea v-model:value="settings.httpLogFormat" :auto-size="{ minRows: 3, maxRows: 8 }"/></a-form-item><a-form-item label="Stream 日志格式" extra="log_format：四层会话日志可使用 $protocol、$bytes_sent、$session_time 等变量。"><a-textarea v-model:value="settings.streamLogFormat" :auto-size="{ minRows: 3, maxRows: 8 }"/></a-form-item><a-button type="primary" @click="save">保存日志格式</a-button></a-form></a-card><a-card class="mt-4" :bordered="false"><template #title><span>预制安全响应头</span></template><template #extra><a-tooltip title="启用后会生成带 always 参数的 add_header 指令。"><span class="section-help"><QuestionCircleOutlined /> 配置说明</span></a-tooltip></template><a-row class="mt-4" :gutter="16"><a-col v-for="item in securityPresets" :key="item.name" :lg="8" :md="12" :xs="24"><div class="security-header-row"><div><div class="font-medium">{{item.name}}</div><div class="text-xs text-gray-500">{{item.label}}：{{item.value}}</div></div><a-switch :checked="isPresetEnabled(item)" checked-children="开启" un-checked-children="关闭" @change="(v:boolean)=>togglePreset(item,v)"/></div></a-col></a-row></a-card><a-card class="mt-4" :bordered="false"><template #title><span>自定义响应头</span></template><template #extra><a-tooltip title="名称支持下拉搜索，也可以直接输入自定义名称；值将在渲染时自动附加 always。"><span class="section-help"><QuestionCircleOutlined /> 配置说明</span></a-tooltip></template><div class="mt-4"><div v-for="(item,index) in customHeaders" :key="index" class="mb-2"><a-space-compact block class="custom-header-row"><a-select v-model:value="item.name" show-search mode="combobox" :options="headerNameOptions" placeholder="Header 名称，可自定义" class="header-name-select"/><a-input v-model:value="item.value" placeholder="Header 值"/><a-button danger @click="removeCustomHeader(index)">删除</a-button></a-space-compact></div><a-space><a-button @click="addCustomHeader">新增响应头</a-button><a-button type="primary" @click="saveHeaders">保存日志与安全配置</a-button></a-space></div></a-card></a-tab-pane><a-tab-pane key="default-pages" tab="默认页面"><a-card :bordered="false"><template #title><span>默认页面配置</span></template><template #extra><a-tooltip title="保存后会作为中心默认页面文件随原生配置生成；Server 或 Location 可按需引用。"><span class="section-help"><QuestionCircleOutlined /> 配置说明</span></a-tooltip></template><a-form layout="vertical" class="mt-4"><a-form-item label="当前生效的默认页面" extra="默认页面只能选择一个；所有 Server 的默认错误页会引用此页面。"><a-select v-model:value="settings.defaultPageKey" :options="defaultPageDefinitions.map(page=>({value:page.key,label:page.label}))"/></a-form-item><a-form-item v-for="page in defaultPageDefinitions" :key="page.key" :label="page.label" :extra="page.hint"><a-textarea v-model:value="settings.defaultPages[page.key]" :auto-size="{ minRows: 8, maxRows: 20 }" :placeholder="`请输入 ${page.label} 内容`"/></a-form-item><a-button type="primary" @click="save">保存默认页面配置</a-button></a-form></a-card></a-tab-pane><a-tab-pane key="server" tab="Server 块"><a-card :bordered="false" title="HTTP Server"><template #extra><a-button @click="router.push('/openresty/upstreams')">前往 Upstream 配置</a-button></template><a-table :columns="columns" :data-source="rows" :loading="loading" :pagination="pager.table.value" row-key="id" @change="(p:any)=>{pager.change(p);loadServers()}"><template #bodyCell="{column,record}"><template v-if="column.key==='ssl'"><a-tag :color="record.sslEnabled?'green':'default'">{{record.sslEnabled?'已启用':'未启用'}}</a-tag></template><template v-else-if="column.key==='root'">{{record.rootPath||'继承 HTTP 配置'}}</template><template v-else-if="column.key==='action'"><a-button type="link" @click="openServer(record)">进入 Server 配置</a-button></template></template></a-table></a-card></a-tab-pane></a-tabs>
<server-editor-drawer v-model:open="serverDrawerOpen" :center-id="centerId" :server="rows.find(v => v.id === editingServerId)" @saved="loadServers"/>
</div>
</template>
